        #include "config_handler.h"

// 预分配的缓冲区，用于存储配置项
#define MAX_CONFIG_NAME_LEN 256
#define MAX_CONFIG_VALUE_LEN 1024
#define MAX_CONFIG_ITEMS 50

typedef struct {
    char name[MAX_CONFIG_NAME_LEN];
    char value[MAX_CONFIG_VALUE_LEN];
} ConfigItem;

static ConfigItem config_buffer[MAX_CONFIG_ITEMS];
static int config_count = 0;

int process_config_item(char* config_name, char* config_value) {
    // 检查输入参数是否为空
    if (config_name == NULL || config_value == NULL) {
        return -1; // 参数错误
    }

    // 检查配置缓冲区是否已满
    if (config_count >= MAX_CONFIG_ITEMS) {
        return -2; // 缓冲区已满
    }

    // 检查配置名称和值的长度，防止缓冲区溢出
    size_t name_len = strlen(config_name);
    size_t value_len = strlen(config_value);

    if (name_len >= MAX_CONFIG_NAME_LEN) {
        return -3; // 配置名称过长
    }

    if (value_len >= MAX_CONFIG_VALUE_LEN) {
        return -4; // 配置值过长
    }

    // 安全地复制配置名称和值到缓冲区
    strncpy(config_buffer[config_count].name, config_name, MAX_CONFIG_NAME_LEN - 1);
    config_buffer[config_count].name[MAX_CONFIG_NAME_LEN - 1] = '\0'; // 确保字符串结束符

    strncpy(config_buffer[config_count].value, config_value, MAX_CONFIG_VALUE_LEN - 1);
    config_buffer[config_count].value[MAX_CONFIG_VALUE_LEN - 1] = '\0'; // 确保字符串结束符

    config_count++; // 增加配置项计数

    return 0; // 成功处理配置项
}
        ]]>
